-- #987 wave 1 (pure additions): Feralas creature abilities, imported from DeltaTho PR 15 file 2026_10_24_44_world.sql.
-- 70 creatures, 293 smart_scripts rows. Only creatures that have NO source_type 0 rows today are written here;
-- scripts that would replace existing rows are wave 2. Filters/fixes: see (not shipped)
-- Idempotent: DELETE of the listed entries then INSERT. AIName is set to SmartAI only where AIName and ScriptName are empty.
-- Undo: DELETE FROM smart_scripts WHERE source_type=0 AND FIND_IN_SET(entryorguid, <entries below>); and
--   UPDATE creature_template SET AIName='' WHERE FIND_IN_SET(entry, <entries below>); (entries that already had AIName SmartAI: see backup in (not shipped).

SET @ENTRIES := '2951,5234,5236,5240,5244,5245,5246,5247,5249,5251,5253,5255,5258,5260,5307,5327,5328,5343,5345,5346,5347,5349,5350,5352,5354,5356,5362,5366,5461,5462,7725,7726,7727,7939,7956,8147,11447,11497,11498,14661,39339,39384,39394,39395,39607,39728,39733,39946,39949,39952,39957,39958,39965,39972,40051,40059,40136,40168,40193,40194,40224,40360,40969,40972,43488,43838,44400,51832,51920,53562';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `AIName` = '' AND `ScriptName` = '' AND FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
